import Foundation
import OpenAPIURLSession
import XCTest
import ColorMatchingAPI

// Anchors the deliverables of issue #5 that are compile-time facts:
//
// 1. The Swift package contains the `ColorMatchingAPI` target generated by
//    swift-openapi-generator from the OpenAPI document published by
//    viamin/color_matching#110 (AC-1).
// 2. The generated module exposes the documented convenience initializer
//    `Client(serverURL:transport:)`, which only exists when the
//    swift-openapi-runtime-backed target is wired into the package.
//
// Until the implementation run adds the target, this file fails to compile
// with "no such module 'ColorMatchingAPI'" — the intended red-phase signal.
// The behavioral coverage of every generated surface (manifest, recent
// sheets, capture creation, measurement upload, judgment upload, ranked
// results) lives in APIClientTests.swift, which drives the generated client
// through the APIClient façade.

final class GeneratedClientTests: XCTestCase {
    func testGeneratedClientModuleIsAvailableAndConstructible() {
        let configuration = URLSessionConfiguration.ephemeral
        configuration.protocolClasses = [MockURLProtocol.self]
        let session = URLSession(configuration: configuration)

        XCTAssertNoThrow(
            ColorMatchingAPI.Client(
                serverURL: URL(string: "https://example.test")!,
                transport: URLSessionTransport(configuration: .init(session: session))
            )
        )
    }
}
